const listDramas = `-- name: ListDramas :many


SELECT d.id, d.title, d.aliases, d.slug, d.summary, d.cover_portrait, d.cover_landscape, d.badge, d.score, d.year, d.status, d.publish_at, d.is_finished, d.sort_weight, d.view_base, d.view_count, d.hot_score, d.latest_episode, d.seo_title, d.seo_desc, d.source, d.created_at, d.updated_at, d.deleted_at
FROM drama d
WHERE d.deleted_at IS NULL
  AND (($1::text IS NULL AND $2::bigint IS NULL)
       OR d.title LIKE $1
       OR aliases_text(d.aliases) LIKE $1
       OR d.id = $2)
  AND ($3::text IS NULL
       OR ($3 = 'scheduled' AND d.status = 'published' AND d.publish_at > now())
       OR ($3 = 'published' AND d.status = 'published' AND (d.publish_at IS NULL OR d.publish_at <= now()))
       OR ($3 NOT IN ('scheduled', 'published') AND d.status = $3))
  AND ($4::bigint IS NULL
       OR EXISTS (SELECT 1 FROM drama_tag dt WHERE dt.drama_id = d.id AND dt.tag_id = $4))
  AND ($5::bigint IS NULL
       OR EXISTS (SELECT 1 FROM drama_term dm WHERE dm.drama_id = d.id AND dm.term_id = $5))
ORDER BY
  CASE WHEN $6::text = 'latest' THEN d.publish_at END DESC NULLS LAST,
  CASE WHEN $6 = 'updated' THEN d.updated_at END DESC,
  CASE WHEN $6 = 'hot' THEN d.hot_score END DESC,
  CASE WHEN $6 = 'recommend' THEN d.sort_weight END DESC,
  d.id DESC
LIMIT $8 OFFSET $7
`

type ListDramasParams struct {
	Pattern    pgtype.Text
	IDEq       pgtype.Int8
	Status     pgtype.Text
	TagID      pgtype.Int8
	TermID     pgtype.Int8
	Sort       string
	PageOffset int32
	PageLimit  int32
}

// 内容域的后台读写（S1-3，docs/03 第 3.1 节）。
// 文本搜索的 LIKE 模式由领域层转义并加 %（pg_bigm 的 GIN 索引支持任意位置匹配）；pattern 为 NULL 表示不按文本搜。
// ---------- 剧集 ----------
// 后台剧集列表（页码分页，不含回收站中的剧）。sort 由领域层按白名单传入，其他值按编号倒序。
// status 为 scheduled 时只含已上架但定时未到点的剧，published 只含已经可见的。
func (q *Queries) ListDramas(ctx context.Context, arg ListDramasParams) ([]Drama, error) {
	rows, err := q.db.Query(ctx, listDramas,
		arg.Pattern,
		arg.IDEq,
		arg.Status,
		arg.TagID,
		arg.TermID,
		arg.Sort,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Drama{}
	for rows.Next() {
		var i Drama
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.Aliases,
			&i.Slug,
			&i.Summary,
			&i.CoverPortrait,
			&i.CoverLandscape,
			&i.Badge,
			&i.Score,
			&i.Year,
			&i.Status,
			&i.PublishAt,
			&i.IsFinished,
			&i.SortWeight,
			&i.ViewBase,
			&i.ViewCount,
			&i.HotScore,
			&i.LatestEpisode,
			&i.SeoTitle,
			&i.SeoDesc,
			&i.Source,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

