const lockTagsForMerge = `-- name: LockTagsForMerge :many
SELECT id, merged_into_id FROM tag WHERE id = ANY($1::bigint[]) ORDER BY id FOR UPDATE
`

type LockTagsForMergeRow struct {
	ID           int64
	MergedIntoID pgtype.Int8
}

// 合并的事务内按编号顺序锁住源标签与目标标签（固定顺序避免死锁）。
func (q *Queries) LockTagsForMerge(ctx context.Context, ids []int64) ([]LockTagsForMergeRow, error) {
	rows, err := q.db.Query(ctx, lockTagsForMerge, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LockTagsForMergeRow{}
	for rows.Next() {
		var i LockTagsForMergeRow
		if err := rows.Scan(&i.ID, &i.MergedIntoID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

